function clampRange(minEl, maxEl, setKey) {
  let vMin = Number(minEl.value);
  let vMax = Number(maxEl.value);
  if (vMin > vMax) {
    // The one being dragged wins — the other snaps to match
    if (setKey === 'dbRequestsMin' || setKey === 'processingMin') vMax = vMin;
    else vMin = vMax;
    minEl.value = vMin;
    maxEl.value = vMax;
  }
  return [vMin, vMax];
}

